@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2 class="mb-3">Kanban Board</h2>

@if (_loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_error
    </div>
}
else
{
    <!-- Stats bar -->
    <div class="d-flex flex-wrap gap-3 mb-3">
        <span class="badge bg-secondary fs-6">Total: @_allTasks.Count</span>
        <span class="badge bg-primary fs-6">To Do: @GetColumn("To Do").Count</span>
        <span class="badge bg-warning text-dark fs-6">In Progress: @GetColumn("In Progress").Count</span>
        <span class="badge bg-success fs-6">Done: @GetColumn("Done").Count</span>
        <span class="badge bg-danger fs-6">Overdue: @_allTasks.Count(t => t.DueDate.Date < DateTime.Today)</span>
    </div>

    <!-- Search bar -->
    <div class="mb-3" style="max-width:400px;">
        <input type="text" class="form-control" placeholder="Search tasks by title…"
               @bind="_searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban columns -->
    <div class="row g-3">
        @foreach (var status in _statuses)
        {
            var columnTasks = GetFilteredColumn(status);
            int idx = Array.IndexOf(_statuses, status);
            <div class="col-md-4">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@status</strong>
                        <span class="badge bg-secondary rounded-pill">@columnTasks.Count</span>
                    </div>
                    <div class="card-body kanban-column">
                        @foreach (var task in columnTasks)
                        {
                            <div class="card mb-2 task-card">
                                <div class="card-body p-2">
                                    <h6 class="card-title mb-1">@task.Title</h6>
                                    <p class="mb-1 text-muted small">@task.Assignee</p>
                                    <div class="d-flex justify-content-between align-items-center mb-1">
                                        <span class="badge priority-@(task.Priority.ToLowerInvariant())">@task.Priority</span>
                                        <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                    </div>
                                    <div class="d-flex justify-content-between mt-1">
                                        @if (idx > 0)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    @onclick="() => MoveTaskAsync(task.Id, _statuses[idx - 1])">
                                                ← Move Left
                                            </button>
                                        }
                                        else
                                        {
                                            <span></span>
                                        }
                                        @if (idx < _statuses.Length - 1)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    @onclick="() => MoveTaskAsync(task.Id, _statuses[idx + 1])">
                                                Move Right →
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (_showForm[status])
                        {
                            <div class="card border-primary mb-2">
                                <div class="card-body p-2">
                                    <div class="mb-2">
                                        <input type="text" class="form-control form-control-sm" placeholder="Title"
                                               @bind="_formData[status].Title" />
                                    </div>
                                    <div class="mb-2">
                                        <input type="text" class="form-control form-control-sm" placeholder="Assignee"
                                               @bind="_formData[status].Assignee" />
                                    </div>
                                    <div class="mb-2">
                                        <select class="form-select form-select-sm" @bind="_formData[status].Priority">
                                            <option value="High">High</option>
                                            <option value="Medium">Medium</option>
                                            <option value="Low">Low</option>
                                        </select>
                                    </div>
                                    <div class="mb-2">
                                        <input type="date" class="form-control form-control-sm"
                                               @bind="_formData[status].DueDate" />
                                    </div>
                                    <div class="d-flex gap-2">
                                        <button class="btn btn-primary btn-sm" @onclick="() => SaveTaskAsync(status)">Save</button>
                                        <button class="btn btn-secondary btn-sm" @onclick="() => CancelForm(status)">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                    <div class="card-footer">
                        <button class="btn btn-outline-primary btn-sm w-100"
                                @onclick="() => ShowAddForm(status)">
                            + Add Task
                        </button>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private readonly string[] _statuses = ["To Do", "In Progress", "Done"];

    private List<TaskItem> _allTasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchText = string.Empty;

    private Dictionary<string, bool> _showForm = new();
    private Dictionary<string, TaskFormModel> _formData = new();

    protected override async Task OnInitializedAsync()
    {
        InitForms();
        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private void InitForms()
    {
        foreach (var s in _statuses)
        {
            _showForm[s] = false;
            _formData[s] = new TaskFormModel();
        }
    }

    private List<TaskItem> GetColumn(string status) =>
        _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumn(string status) =>
        _allTasks
            .Where(t => t.Status == status &&
                        (string.IsNullOrWhiteSpace(_searchText) ||
                         t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)))
            .ToList();

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = _allTasks.FirstOrDefault(t => t.Id == taskId);
            if (task is not null)
            {
                _allTasks[_allTasks.IndexOf(task)] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }

    private void ShowAddForm(string status)
    {
        _formData[status] = new TaskFormModel();
        _showForm[status] = true;
    }

    private void CancelForm(string status)
    {
        _showForm[status] = false;
    }

    private async Task SaveTaskAsync(string status)
    {
        var form = _formData[status];
        if (string.IsNullOrWhiteSpace(form.Title))
            return;

        try
        {
            var created = await TaskService.CreateTaskAsync(form.Title, form.Assignee, form.Priority, form.DueDate);
            // The service creates with default status; override to the target column
            _allTasks.Add(created with { Status = status });
            _showForm[status] = false;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }

    private class TaskFormModel
    {
        public string Title { get; set; } = string.Empty;
        public string Assignee { get; set; } = string.Empty;
        public string Priority { get; set; } = "Medium";
        public DateTime DueDate { get; set; } = DateTime.Today.AddDays(7);
    }
}

